from .rules import applicable_rate


def price_line(catalog, sku, quantity):
    """Price one order line. Every price in the system comes through here."""
    unit = catalog.unit_price(sku)
    rate = applicable_rate(sku, quantity)
    return round(unit * quantity * rate, 2)

