#: Per-SKU overrides, applied before any quantity rule.
SKU_RATES = {}


def applicable_rate(sku, quantity):
    """The multiplier applied to a line. 1.0 means list price."""
    if sku in SKU_RATES:
        return SKU_RATES[sku]
    return 1.0

