import unittest

from inventory import Catalog, Order


class TestExistingBehaviour(unittest.TestCase):
    def setUp(self):
        self.catalog = Catalog({'widget': 10.0, 'bolt': 2.0})

    def test_a_single_line_is_list_price(self):
        order = Order(self.catalog)
        order.add_line('widget', 1)
        self.assertEqual(order.total(), 10.0)

    def test_small_quantities_are_not_discounted(self):
        order = Order(self.catalog)
        order.add_line('widget', 3)
        self.assertEqual(order.total(), 30.0)

    def test_quantity_must_be_positive(self):
        order = Order(self.catalog)
        with self.assertRaises(ValueError):
            order.add_line('widget', 0)


if __name__ == '__main__':
    unittest.main()
